<?php
declare(strict_types=1);
namespace App\Delivery\Http\Business;
use App\Application\Business\{BusinessAccess,BusinessDocuments,BusinessInput,BusinessReports,BusinessViolation,CurrencyPreference,Merchandising};
use App\Application\Authorization\DurableAuthorizationViolation;
use App\Application\Pos\PosTransactionViolation;
use App\Delivery\Http\SafeErrorEnvelope;
use Illuminate\Http\Request;
use Illuminate\Database\QueryException;
use Inertia\Inertia;
// Author by Lab | zefry. Every read/download and write requires current server authority.
final readonly class MerchandisingController {
    public function __construct(private Merchandising $products,private BusinessReports $reports,private BusinessAccess $access,private BusinessDocuments $documents){}
    private function filters(Request $r):array {$v=[];foreach(['q','category','brand','status','from','to','locale']as$k)if($r->query($k)!==null)$v[$k]=BusinessInput::text($r->query($k),120,true);return $v;}
    public function catalog(Request $r):mixed {return $this->respond($r,fn()=>Inertia::render('Business/Products',['products'=>$this->products->products($this->filters($r),BusinessInput::integer($r->query('page','1'),1,10000)),'filters'=>$this->filters($r),'preferences'=>$this->products->preferences()]));}
    public function settings(Request $r):mixed {return $this->respond($r,fn()=>Inertia::render('Business/Settings',['preferences'=>$this->products->settings(),'currencies'=>CurrencyPreference::OPTIONS]));}
    public function reports(Request $r):mixed {return $this->respond($r,function()use($r){$v=$this->reports->available();if(!$v)throw new BusinessViolation('REPORT_PERMISSION_DENIED',403);return Inertia::render('Business/Reports',['reports'=>$v,'preferences'=>$this->products->preferences()]);});}
    public function trend(Request $r):mixed {return $this->respond($r,fn()=>response()->json($this->reports->trend($this->filters($r))));}
    private function input(Request $r):array {if(strlen($r->getContent())>1000000)throw new BusinessViolation('REQUEST_TOO_LARGE',413);$v=$r->except('_token');BusinessInput::fields($v,['operation_id','data']);if(!is_array($v['data']))throw new BusinessViolation('INVALID_FIELDS');return $v;}
    private function correlation(Request $r):string {return (string)$r->attributes->get('oneqay.correlation_id','correlation-missing');}
    public function saveProduct(Request $r):mixed {return $this->respond($r,function()use($r){$v=$this->input($r);return response()->json(['record'=>$this->products->saveProduct(BusinessInput::text($v['operation_id'],80),$v['data'],$this->correlation($r))]);});}
    public function saveSettings(Request $r):mixed {return $this->respond($r,function()use($r){$v=$this->input($r);return response()->json(['record'=>$this->products->saveSettings(BusinessInput::text($v['operation_id'],80),$v['data'],$this->correlation($r))]);});}
    public function preview(Request $r):mixed {return $this->respond($r,function()use($r){$this->access->require('pos.catalog.prepare');$this->access->require('pos.inventory.baseline');$r->validate(['file'=>'required|file|max:1953']);$file=$r->file('file');if(!$file||!$file->isValid())throw new BusinessViolation('INVALID_IMPORT_FILE');$rows= $this->documents->importProducts((string)file_get_contents($file->getRealPath()),strtolower($file->getClientOriginalExtension()));return response()->json($this->products->preview($rows)+['source_rows'=>$rows]);});}
    public function commit(Request $r):mixed {return $this->respond($r,function()use($r){$v=$this->input($r);BusinessInput::fields($v['data'],['rows','preview_digest','settings_version']);return response()->json(['record'=>$this->products->import(BusinessInput::text($v['operation_id'],80),BusinessInput::rows($v['data']['rows'],500),BusinessInput::text($v['data']['preview_digest'],64),BusinessInput::integer($v['data']['settings_version'],0,1000000000),$this->correlation($r))]);});}
    public function template(Request $r):mixed {return $this->respond($r,function(){$this->access->require('pos.catalog.prepare');return response($this->documents->productTemplate(),200,['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition'=>'attachment; filename="oneQay-template-produk.xlsx"']);});}
    public function download(Request $r,string $report):mixed {return $this->respond($r,function()use($r,$report){$format=$r->query('format','xlsx');if(!in_array($format,['pdf','xlsx'],true))throw new BusinessViolation('INVALID_EXPORT_FORMAT');$v=$this->reports->read($report,$this->filters($r));$raw=$this->documents->report($v,$format);return response($raw,200,['Content-Type'=>$format==='pdf'?'application/pdf':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet','Content-Disposition'=>'attachment; filename="oneQay-'.$report.'-'.gmdate('Ymd-His').'.'.$format.'"','X-Report-Rows'=>(string)$v['count'],'X-Content-Type-Options'=>'nosniff']);});}
    private function respond(Request $r,callable $work):mixed {try{$v=$work();if(method_exists($v,'toResponse'))$v=$v->toResponse($r);$v->headers->set('Cache-Control','no-store, private');return $v;}catch(DurableAuthorizationViolation){$code='BUSINESS_PERMISSION_DENIED';$status=403;}catch(BusinessViolation $e){$code=$e->reason;$status=$e->status;}catch(PosTransactionViolation|\InvalidArgumentException){$code='PRODUCT_SAVE_REJECTED';$status=422;}catch(\App\Application\Persistence\DurablePersistenceViolation){$code='BUSINESS_STORAGE_UNAVAILABLE';$status=503;}catch(QueryException $e){$code=str_starts_with((string)($e->errorInfo[0]??''),'23')?'DUPLICATE_OR_INVALID_REFERENCE':'BUSINESS_STORAGE_UNAVAILABLE';$status=$code==='BUSINESS_STORAGE_UNAVAILABLE'?503:409;}return response()->json(SafeErrorEnvelope::make($code,$this->correlation($r)),$status,['Cache-Control'=>'no-store, private']);}
}
